INSERT INTO content_blocks (section_id, type, content_json, sort_order) VALUES ((SELECT id FROM sections WHERE slug='overview' AND plugin_id=(SELECT id FROM plugins WHERE slug='WebUIX')), 'html', '{"html":"<p data-lang="zh">WebUIX 是自研的 HTML/CSS UI 渲染引擎，作为原生 UMG 插件运行在 Unreal Engine 中。无浏览器进程、无 JavaScript 引擎、无 CEF/Chromium — 用熟悉的 HTML/CSS 语法构建游戏 UI，通过 Blueprint 完成所有交互逻辑。</p>\n  <p data-lang="en">WebUIX is a self-developed HTML/CSS UI rendering engine running as a native UMG plugin in Unreal Engine. No browser process, no JavaScript engine, no CEF/Chromium — build game UIs with familiar HTML/CSS and handle all interaction logic through Blueprint.</p>\n  <div class="grid2" style="margin-top:16px">\n    <div class="card">\n      <h4 data-lang="zh">全平台支持</h4><h4 data-lang="en">Cross-Platform</h4>\n      <p data-lang="zh">Win64、macOS、Linux、Android、iOS — 一套 HTML/CSS 在所有平台上渲染一致</p>\n      <p data-lang="en">Win64, macOS, Linux, Android, iOS — one set of HTML/CSS renders identically everywhere</p>\n    </div>\n    <div class="card">\n      <h4 data-lang="zh">高性能原生渲染</h4><h4 data-lang="en">High-Performance Native Rendering</h4>\n      <p data-lang="zh">Direct RHI 渲染，无浏览器进程开销。支持跨帧缓存、脏区增量更新、独立 RT 拖拽预览</p>\n      <p data-lang="en">Direct RHI rendering, no browser process overhead. Cross-frame caching, dirty-region updates, separate RT drag preview</p>\n    </div>\n    <div class="card">\n      <h4 data-lang="zh">HTML/CSS 开发体验</h4><h4 data-lang="en">HTML/CSS Workflow</h4>\n      <p data-lang="zh">Box model、Flexbox、过渡动画、CSS 滤镜、UI 音效 — 用 Web 前端技能构建游戏 UI</p>\n      <p data-lang="en">Box model, flexbox, transitions, CSS filters, UI sound effects — use web frontend skills for game UI</p>\n    </div>\n    <div class="card">\n      <h4 data-lang="zh">Blueprint 深度集成</h4><h4 data-lang="en">Deep Blueprint Integration</h4>\n      <p data-lang="zh">事件桥（OnClick 调 UFUNCTION）、数据模型绑定、完整 DOM API、自定义组件系统</p>\n      <p data-lang="en">Event bridge (OnClick calls UFUNCTION), data model binding, full DOM API, custom component system</p>\n    </div>\n    <div class="card">\n      <h4 data-lang="zh">自定义 HTML 组件</h4><h4 data-lang="en">Custom Components</h4>\n      <p data-lang="zh">在 Blueprint 中创建新 HTML 标签，定义自定义属性与事件。组件内 UFUNCTION 可直接在 HTML 中调用 — 类似 Web Components 开发模式</p>\n      <p data-lang="en">Create new HTML tags in Blueprint with custom attributes and events. Component UFUNCTIONs are directly callable from HTML — Web Components-like development</p>\n    </div>\n    <div class="card">\n      <h4 data-lang="zh">内置调试控制台</h4><h4 data-lang="en">Built-in Debug Console</h4>\n      <p data-lang="zh">F8 打开 — 实时 DOM 树、元素选择器、样式计算面板、渲染统计、脏区可视化</p>\n      <p data-lang="en">Press F8 — live DOM tree, element picker, computed styles, render stats, dirty region visualization</p>\n    </div>\n  </div>"}', 0);
INSERT INTO content_blocks (section_id, type, content_json, sort_order) VALUES ((SELECT id FROM sections WHERE slug='quick-start' AND plugin_id=(SELECT id FROM plugins WHERE slug='WebUIX')), 'html', '{"html":"<div class="subsection">\n    <h3>1. <span data-lang="zh">启用插件</span><span data-lang="en">Enable Plugin</span></h3>\n    <p data-lang="zh">在 Edit → Plugins 中启用 <strong>WebUIX</strong>，重启编辑器。</p>\n    <p data-lang="en">Enable <strong>WebUIX</strong> in Edit → Plugins and restart the editor.</p>\n  </div>\n  <div class="subsection" style="margin-top:12px">\n    <h3>2. <span data-lang="zh">创建 HTML/CSS 资产</span><span data-lang="en">Create Assets</span></h3>\n    <p data-lang="zh">在 Content Browser 右键 → <strong>WebUIX → HTML Document</strong> 和 <strong>CSS Stylesheet</strong>。双击资产打开内置代码编辑器。</p>\n    <p data-lang="en">Right-click in Content Browser → <strong>WebUIX → HTML Document</strong> and <strong>CSS Stylesheet</strong>. Double-click to open the built-in code editor.</p>\n    <pre><code class="language-xml">&lt;!DOCTYPE html&gt;\n&lt;html&gt;\n&lt;head&gt;\n  &lt;link rel=&quot;stylesheet&quot; href=&quot;/WebUIX/MyPlugin/Styles.css&quot; /&gt;\n&lt;/head&gt;\n&lt;body&gt;\n  &lt;div class=&quot;title&quot;&gt;{{PlayerName}}&lt;/div&gt;\n  &lt;p&gt;Health: {{Model.Health}} / {{Model.MaxHealth}}&lt;/p&gt;\n  &lt;div class=&quot;hp-bar&quot;&gt;&lt;div class=&quot;hp-fill&quot;&gt;&lt;/div&gt;&lt;/div&gt;\n  &lt;button OnClick=&quot;OnStartClicked&quot;&gt;Start Game&lt;/button&gt;\n&lt;/body&gt;\n&lt;/html&gt;</code></pre>\n  </div>\n  <div class="subsection" style="margin-top:12px">\n    <h3>3. <span data-lang="zh">创建 Widget Blueprint</span><span data-lang="en">Create Widget Blueprint</span></h3>\n    <p data-lang="zh">新建 Widget Blueprint，父类设为 <strong>UWebUIXUserWidget</strong>。在 Class Defaults 中设置 <code>DocumentAsset</code>。</p>\n    <p data-lang="en">Create a Widget Blueprint with parent class <strong>UWebUIXUserWidget</strong>. Set <code>DocumentAsset</code> in Class Defaults.</p>\n    <p data-lang="zh">或者在已有 Widget Blueprint 中直接添加 <strong>WebUIX Widget</strong> 组件（使用 UWebUIXWidget）。</p>\n    <p data-lang="en">Or add a <strong>WebUIX Widget</strong> component directly to an existing Widget Blueprint (uses UWebUIXWidget).</p>\n  </div>\n  <div class="subsection" style="margin-top:12px">\n    <h3>4. <span data-lang="zh">数据绑定</span><span data-lang="en">Data Binding</span></h3>\n    <pre><code class="language-cpp">// Blueprint or C++:\nWidget->SetModelNumber("Health", 85.0f);\nWidget->SetModelNumber("MaxHealth", 100.0f);\nWidget->NotifyContextChanged();</code></pre>\n  </div>\n  <div class="subsection" style="margin-top:12px">\n    <h3>5. <span data-lang="zh">事件处理</span><span data-lang="en">Handle Events</span></h3>\n    <p data-lang="zh">在 Widget Blueprint 中添加名为 <code>OnStartClicked</code> 的 Blueprint 事件。按钮点击时自动调用。</p>\n    <p data-lang="en">Add a Blueprint event named <code>OnStartClicked</code> in the Widget Blueprint. It will be called when the button is clicked.</p>\n  </div>\n  <div class="subsection" style="margin-top:12px">\n    <h3>6. <span data-lang="zh">3D Widget 支持</span><span data-lang="en">3D Widget Support</span></h3>\n    <p data-lang="zh">WebUIX 支持 UE 的 UWidgetComponent 在 3D 世界空间中渲染。在 UWebUIXUserWidget 上启用 <code>bAutoRouteWidgetInteractionButtons</code> 可自动路由鼠标光标。IME 和文本输入与屏幕空间一致。</p>\n    <p data-lang="en">WebUIX supports UWidgetComponent for 3D world-space UI. Enable <code>bAutoRouteWidgetInteractionButtons</code> on UWebUIXUserWidget for automatic mouse cursor routing. IME and text input work the same as in screen-space.</p>\n  </div>"}', 0);
INSERT INTO content_blocks (section_id, type, content_json, sort_order) VALUES ((SELECT id FROM sections WHERE slug='editor-workflow' AND plugin_id=(SELECT id FROM plugins WHERE slug='WebUIX')), 'html', '{"html":"<div class="grid2">\n    <div class="card">\n      <h4><span data-lang="zh">内置代码编辑器</span><span data-lang="en">Built-in Code Editor</span></h4>\n      <p data-lang="zh">双击 HTML/CSS 资产打开，支持语法高亮、Ctrl+S 保存、Alt+Shift+F 格式化、自动补全（标签、属性、事件、CSS 属性、资源路径）。编辑器默认置顶。</p>\n      <p data-lang="en">Double-click HTML/CSS assets. Syntax highlighting, Ctrl+S save, Alt+Shift+F format, autocomplete (tags, attributes, events, CSS properties, resource paths). Editor is topmost by default.</p>\n    </div>\n    <div class="card">\n      <h4><span data-lang="zh">外部文件同步与热重载</span><span data-lang="en">External Sync &amp; Hot Reload</span></h4>\n      <p data-lang="zh">可指定外部 .html/.css 文件路径，编辑后自动检测变化并热重载。适合开发期快速迭代。正式项目推荐使用 UWebUIXHtmlDocument 资产。</p>\n      <p data-lang="en">Point to external .html/.css files; changes are auto-detected and hot-reloaded. Best for fast iteration during development. Use UWebUIXHtmlDocument assets for production.</p>\n    </div>\n    <div class="card">\n      <h4><span data-lang="zh">资源选择器</span><span data-lang="en">Resource Picker</span></h4>\n      <p data-lang="zh">CSS 中写 <code>url(...)</code> 时可打开资源选择器，按类型（图片、音频、字体等）筛选 UE 资产。音频资源支持预览播放。</p>\n      <p data-lang="en">Open the resource picker when writing <code>url(...)</code> in CSS, filter by type (image, audio, font, etc.). Audio resources support preview playback.</p>\n    </div>\n    <div class="card">\n      <h4><span data-lang="zh">诊断面板</span><span data-lang="en">Diagnostics</span></h4>\n      <p data-lang="zh">编辑器底部状态栏显示诊断摘要（错误/警告），可跳转上一个/下一个诊断并复制诊断文本。</p>\n      <p data-lang="en">Status bar at the bottom of the editor shows diagnostic summary (errors/warnings). Jump to previous/next diagnostic and copy diagnostic text.</p>\n    </div>\n  </div>"}', 0);
INSERT INTO content_blocks (section_id, type, content_json, sort_order) VALUES ((SELECT id FROM sections WHERE slug='html-css-basics' AND plugin_id=(SELECT id FROM plugins WHERE slug='WebUIX')), 'html', '{"html":"<div class="subsection">\n    <h3><span data-lang="zh">支持的 HTML 标签</span><span data-lang="en">Supported HTML Tags</span></h3>\n    <div class="code-tags">\n      <code>rml</code><code>head</code><code>body</code><code>link</code><code>title</code>\n      <code>div</code><code>section</code><code>article</code><code>header</code><code>footer</code><code>main</code><code>nav</code><code>aside</code>\n      <code>span</code><code>p</code><code>h1</code><code>h2</code><code>h3</code><code>h4</code><code>h5</code><code>h6</code>\n      <code>ul</code><code>ol</code><code>li</code><code>table</code><code>thead</code><code>tbody</code><code>tr</code><code>td</code><code>th</code>\n      <code>button</code><code>input</code><code>textarea</code><code>select</code><code>option</code><code>label</code>\n      <code>img</code><code>progress</code><code>a</code><code>svg</code>\n    </div>\n    <p data-lang="zh" style="margin-top:8px">扩展元素：<code>drag-area</code> <code>drag-cell</code> <code>drag-item</code> <code>handle</code> <code>radio-group</code> <code>radio-option</code> <code>checkbox-group</code> <code>checkbox-option</code> <code>dropdown</code> <code>dropdown-option</code> <code>password</code> <code>modal</code> <code>modal-title</code> <code>modal-footer</code> <code>tooltips</code> <code>tooltips-content</code> <code>animation-watch</code></p>\n    <p data-lang="en" style="margin-top:8px">Extension elements: <code>drag-area</code> <code>drag-cell</code> <code>drag-item</code> <code>handle</code> <code>radio-group</code> <code>radio-option</code> <code>checkbox-group</code> <code>checkbox-option</code> <code>dropdown</code> <code>dropdown-option</code> <code>password</code> <code>modal</code> <code>modal-title</code> <code>modal-footer</code> <code>tooltips</code> <code>tooltips-content</code> <code>animation-watch</code></p>\n  </div>\n\n  <div class="subsection" style="margin-top:12px">\n    <h3><span data-lang="zh">CSS 属性速查</span><span data-lang="en">CSS Property Reference</span></h3>\n    <div class="grid2">\n      <div class="card">\n        <h4><span data-lang="zh">布局与尺寸</span><span data-lang="en">Layout &amp; Sizing</span></h4>\n        <div class="code-tags"><code>display</code><code>position</code><code>position:sticky</code><code>inset</code><code>top</code><code>right</code><code>bottom</code><code>left</code><code>width</code><code>height</code><code>min/max-width</code><code>min/max-height</code><code>overflow</code><code>z-index</code></div>\n      </div>\n      <div class="card">\n        <h4><span data-lang="zh">盒模型</span><span data-lang="en">Box Model</span></h4>\n        <div class="code-tags"><code>margin</code><code>padding</code><code>border</code><code>border-width</code><code>border-color</code><code>border-radius</code><code>box-sizing</code><code>box-shadow</code></div>\n      </div>\n      <div class="card">\n        <h4><span data-lang="zh">文字</span><span data-lang="en">Typography</span></h4>\n        <div class="code-tags"><code>font-family</code><code>font-size</code><code>font-weight</code><code>font-style</code><code>line-height</code><code>letter-spacing</code><code>text-align</code><code>text-decoration</code><code>text-overflow</code><code>white-space</code><code>word-break</code><code>color</code><code>text-shadow</code></div>\n      </div>\n      <div class="card">\n        <h4><span data-lang="zh">Flexbox</span></h4>\n        <div class="code-tags"><code>flex-direction</code><code>flex-wrap</code><code>flex</code><code>flex-grow</code><code>flex-shrink</code><code>align-items</code><code>align-content</code><code>align-self</code><code>justify-content</code><code>row-gap</code><code>column-gap</code></div>\n      </div>\n      <div class="card">\n        <h4><span data-lang="zh">背景与渲染</span><span data-lang="en">Background &amp; Effects</span></h4>\n        <div class="code-tags"><code>background-color</code><code>background-image</code><code>background-size</code><code>linear-gradient</code><code>radial-gradient</code><code>opacity</code><code>transform</code><code>transform-origin</code><code>transition</code><code>animation</code><code>image-color</code></div>\n      </div>\n      <div class="card">\n        <h4><span data-lang="zh">单位与值</span><span data-lang="en">Units &amp; Values</span></h4>\n        <div class="code-tags"><code>dp</code><code>em</code><code>rem</code><code>vw</code><code>vh</code><code>%</code><code>calc()</code><code>min()</code><code>max()</code><code>inherit</code><code>initial</code><code>unset</code></div>\n      </div>\n    </div>\n  </div>\n\n  <div class="subsection" style="margin-top:12px">\n    <h3><span data-lang="zh">Pseudo-class 状态</span><span data-lang="en">Pseudo-class States</span></h3>\n    <div class="code-tags">\n      <code>:hover</code><code>:active</code><code>:focus</code><code>:checked</code><code>:disabled</code>\n      <code>:first-child</code><code>:last-child</code><code>:nth-child(n)</code><code>:not(...)</code>\n    </div>\n    <p data-lang="zh" style="margin-top:8px">扩展状态：<code>:selected</code> <code>:open</code> <code>:dragging</code> <code>:valid</code> <code>:invalid</code> <code>:hot</code> <code>:occupied</code>。部分 pseudo-state 会同步为 CSS class（<code>.selected</code> <code>.open</code> <code>.disabled</code>）。</p>\n    <p data-lang="en" style="margin-top:8px">Extension states: <code>:selected</code> <code>:open</code> <code>:dragging</code> <code>:valid</code> <code>:invalid</code> <code>:hot</code> <code>:occupied</code>. Some are mirrored to CSS classes (<code>.selected</code> <code>.open</code> <code>.disabled</code>).</p>\n  </div>\n\n  <div class="subsection" style="margin-top:12px">\n    <h3><span data-lang="zh">资源引用</span><span data-lang="en">Asset References</span></h3>\n    <p data-lang="zh">图片和音频通过 UE 资产路径引用：</p>\n    <p data-lang="en">Images and audio are referenced via UE asset paths:</p>\n    <pre><code class="language-html">&lt;img src=&quot;/Game/UI/Icons/Sword.Sword&quot; /&gt;</code></pre>\n    <pre><code class="language-css">.icon { background-image: url(&quot;/Game/UI/Icons/Sword.Sword&quot;); }\n.banner { background: url(banner.png) center / cover no-repeat; }</code></pre>\n    <p data-lang="zh">散列图片文件（PNG、JPG）在 Cook 时嵌入到 UWebUIXHtmlDocument 的派生数据中。</p>\n    <p data-lang="en">Loose image files (PNG, JPG) are embedded in UWebUIXHtmlDocument derived data at cook time.</p>\n  </div>"}', 0);
INSERT INTO content_blocks (section_id, type, content_json, sort_order) VALUES ((SELECT id FROM sections WHERE slug='css-filters' AND plugin_id=(SELECT id FROM plugins WHERE slug='WebUIX')), 'html', '{"html":"<p data-lang="zh">WebUIX 支持多种 CSS 滤镜效果，可用于 UI 动效、背景模糊和视觉氛围增强。</p>\n  <p data-lang="en">WebUIX supports multiple CSS filter effects for UI motion, background blur, and visual atmosphere.</p>\n\n  <div class="subsection" style="margin-top:12px">\n    <h3>filter</h3>\n    <p data-lang="zh"><code>filter</code> 属性对元素及其子元素的渲染结果应用图形效果。</p>\n    <p data-lang="en">The <code>filter</code> property applies graphical effects to the element and its descendants.</p>\n    <table>\n      <tr><th><span data-lang="zh">函数</span><span data-lang="en">Function</span></th><th><span data-lang="zh">说明</span><span data-lang="en">Description</span></th><th><span data-lang="zh">示例</span><span data-lang="en">Example</span></th></tr>\n      <tr><td><code>blur()</code></td><td data-lang="zh">高斯模糊</td><td data-lang="en">Gaussian blur</td><td><code>filter: blur(4dp);</code></td></tr>\n      <tr><td><code>brightness()</code></td><td data-lang="zh">亮度调节（0=黑，1=原始，>1=更亮）</td><td data-lang="en">Brightness (0=black, 1=original, >1=brighter)</td><td><code>filter: brightness(1.2);</code></td></tr>\n      <tr><td><code>contrast()</code></td><td data-lang="zh">对比度调节（0=灰，1=原始，>1=更强）</td><td data-lang="en">Contrast (0=gray, 1=original, >1=stronger)</td><td><code>filter: contrast(1.15);</code></td></tr>\n      <tr><td><code>saturate()</code></td><td data-lang="zh">饱和度调节（0=去色，1=原始，>1=更鲜艳）</td><td data-lang="en">Saturation (0=desaturated, 1=original, >1=vivid)</td><td><code>filter: saturate(1.5);</code></td></tr>\n      <tr><td><code>drop-shadow()</code></td><td data-lang="zh">投影（类似 box-shadow 但跟随轮廓）</td><td data-lang="en">Drop shadow (follows content contour)</td><td><code>filter: drop-shadow(0 4dp 8dp #00000066);</code></td></tr>\n    </table>\n    <pre><code class="language-css">.card {\n  filter: drop-shadow(0 10dp 24dp #00000066);\n}\n.card:hover {\n  filter: brightness(1.1) drop-shadow(0 14dp 32dp #00000088);\n  transition: filter 200ms;\n}\n.inactive {\n  filter: brightness(0.6) saturate(0.3);\n}</code></pre>\n  </div>\n\n  <div class="subsection" style="margin-top:12px">\n    <h3>backdrop-filter</h3>\n    <p data-lang="zh"><code>backdrop-filter</code> 对元素<em>背后</em>区域的内容应用滤镜（常用于毛玻璃效果）。</p>\n    <p data-lang="en"><code>backdrop-filter</code> applies filters to the area <em>behind</em> the element (useful for frosted glass effects).</p>\n    <pre><code class="language-css">.glass-panel {\n  background: rgba(255,255,255,.12);\n  backdrop-filter: blur(16dp);\n  border: 1dp rgba(255,255,255,.2);\n  border-radius: 16dp;\n}\n.overlay {\n  backdrop-filter: blur(8dp) brightness(0.5);\n}</code></pre>\n    <div class="callout">\n      <p data-lang="zh">backdrop-filter 会引入额外的 RHI 渲染通道（BackdropFilterPass）。大量使用可能增加 GPU 开销，建议在调试控制台的 Paint 面板中查看 BackdropFilterPassCount 统计。</p>\n      <p data-lang="en">backdrop-filter introduces additional RHI render passes (BackdropFilterPass). Heavy usage may increase GPU cost; check BackdropFilterPassCount in the Debug Console Paint panel.</p>\n    </div>\n  </div>\n\n  <div class="subsection" style="margin-top:12px">\n    <h3><span data-lang="zh">filter 与动画</span><span data-lang="en">Filter &amp; Animation</span></h3>\n    <p data-lang="zh">filter 属性支持 CSS transition 和 animation 平滑过渡：</p>\n    <p data-lang="en">Filter supports CSS transitions and animations for smooth interpolation:</p>\n    <pre><code class="language-css">.btn {\n  filter: brightness(1);\n  transition: filter 150ms ease;\n}\n.btn:hover { filter: brightness(1.15); }\n.btn:active { filter: brightness(0.92); }\n\n@keyframes pulse-glow {\n  0%, 100% { filter: drop-shadow(0 0 4dp #38bdf844); }\n  50%      { filter: drop-shadow(0 0 16dp #38bdf8aa); }\n}\n.glow { animation: pulse-glow 2s ease-in-out infinite; }</code></pre>\n  </div>"}', 0);
INSERT INTO content_blocks (section_id, type, content_json, sort_order) VALUES ((SELECT id FROM sections WHERE slug='ui-sound' AND plugin_id=(SELECT id FROM plugins WHERE slug='WebUIX')), 'html', '{"html":"<p data-lang="zh">WebUIX 支持通过 CSS 属性 <code>background-sound</code> 在元素交互（hover、active、focus）时自动播放 UE 音频资产（USoundBase）。无需编写 Blueprint 逻辑。</p>\n  <p data-lang="en">WebUIX supports playing UE audio assets (USoundBase) automatically on element interaction (hover, active, focus) via the <code>background-sound</code> CSS property. No Blueprint logic required.</p>\n\n  <div class="subsection" style="margin-top:12px">\n    <h3><span data-lang="zh">CSS 属性</span><span data-lang="en">CSS Properties</span></h3>\n    <table>\n      <tr><th><span data-lang="zh">属性</span><span data-lang="en">Property</span></th><th><span data-lang="zh">类型</span><span data-lang="en">Type</span></th><th><span data-lang="zh">默认值</span><span data-lang="en">Default</span></th><th><span data-lang="zh">说明</span><span data-lang="en">Description</span></th></tr>\n      <tr><td><code>background-sound</code></td><td>URI</td><td>—</td><td data-lang="zh">指向 USoundBase 资产路径</td><td data-lang="en">USoundBase asset path</td></tr>\n      <tr><td><code>background-sound-volume</code></td><td>float</td><td><code>1.0</code></td><td data-lang="zh">音量乘数（>=0）</td><td data-lang="en">Volume multiplier (>=0)</td></tr>\n      <tr><td><code>background-sound-pitch</code></td><td>float</td><td><code>1.0</code></td><td data-lang="zh">音高乘数（>=0.01）</td><td data-lang="en">Pitch multiplier (>=0.01)</td></tr>\n      <tr><td><code>background-sound-cooldown</code></td><td>time</td><td><code>0</code></td><td data-lang="zh">播放冷却时间，支持 s/ms 后缀</td><td data-lang="en">Cooldown between plays; supports s/ms suffix</td></tr>\n    </table>\n  </div>\n\n  <div class="subsection" style="margin-top:12px">\n    <h3><span data-lang="zh">触发时机</span><span data-lang="en">Trigger Timing</span></h3>\n    <p data-lang="zh">音效在以下 pseudo-class 激活时自动播放：</p>\n    <p data-lang="en">Sound plays automatically when these pseudo-classes are activated:</p>\n    <ul>\n      <li><code>:hover</code> — <span data-lang="zh">鼠标悬停时</span><span data-lang="en">On mouse hover</span></li>\n      <li><code>:active</code> — <span data-lang="zh">按下时（鼠标/触摸）</span><span data-lang="en">On press (mouse/touch)</span></li>\n      <li><code>:focus</code> — <span data-lang="zh">获得焦点时（Tab 导航等）</span><span data-lang="en">On focus (Tab navigation etc.)</span></li>\n    </ul>\n  </div>\n\n  <div class="subsection" style="margin-top:12px">\n    <h3><span data-lang="zh">使用示例</span><span data-lang="en">Usage Examples</span></h3>\n    <p data-lang="zh">资产路径使用 <code>asset:///</code> 前缀（编辑器资源选择器自动补全）：</p>\n    <p data-lang="en">Asset paths use the <code>asset:///</code> prefix (resource picker auto-completes):</p>\n    <pre><code class="language-css">/* Hover: glass sound, 50ms cooldown */\n.ui-hover-sound:hover {\n  background-sound: url("asset:///WebUIX/WebUIX/Sound/glass_001.glass_001");\n  background-sound-volume: 0.35;\n  background-sound-cooldown: 0.05s;\n}\n\n/* Click: crisp click sound, higher volume */\n.ui-click-sound:active {\n  background-sound: url("asset:///WebUIX/WebUIX/Sound/click_003.click_003");\n  background-sound-volume: 0.55;\n  background-sound-cooldown: 0.05s;\n}\n\n/* Focus: focus feedback sound */\n.ui-focus-sound:focus {\n  background-sound: url("asset:///WebUIX/WebUIX/Sound/close_002.close_002");\n  background-sound-volume: 0.28;\n}</code></pre>\n    <pre><code class="language-html">&lt;button class=&quot;btn primary ui-hover-sound ui-click-sound ui-focus-sound&quot;&gt;\n  Confirm\n&lt;/button&gt;</code></pre>\n  </div>\n\n  <div class="callout">\n    <p data-lang="zh"><strong>提示：</strong>音效资产通过软引用（TWeakObjectPtr）管理，随文档自动 Cook 到包中。在 CSS 编辑器中使用资源选择器筛选 Audio 类型即可快速插入资产路径。</p>\n    <p data-lang="en"><strong>Tip:</strong> Sound assets are managed via soft references (TWeakObjectPtr) and automatically cooked into the package. Use the resource picker with Audio filter in the CSS editor to quickly insert asset paths.</p>\n  </div>"}', 0);
INSERT INTO content_blocks (section_id, type, content_json, sort_order) VALUES ((SELECT id FROM sections WHERE slug='animations' AND plugin_id=(SELECT id FROM plugins WHERE slug='WebUIX')), 'html', '{"html":"<div class="subsection">\n    <h3>CSS Transitions</h3>\n    <p data-lang="zh">支持对所有可动画属性的平滑过渡。常用可动画属性：<code>color</code> <code>background-color</code> <code>opacity</code> <code>transform</code> <code>filter</code> <code>width</code> <code>height</code> <code>margin</code> <code>padding</code>。</p>\n    <p data-lang="en">Smooth transitions on all animatable properties. Common: <code>color</code> <code>background-color</code> <code>opacity</code> <code>transform</code> <code>filter</code> <code>width</code> <code>height</code> <code>margin</code> <code>padding</code>.</p>\n    <pre><code class="language-css">.card {\n  transform: scale(1);\n  filter: brightness(1);\n  transition: transform 180ms ease, filter 150ms;\n}\n.card:hover { transform: scale(1.04); filter: brightness(1.1); }</code></pre>\n  </div>\n\n  <div class="subsection" style="margin-top:12px">\n    <h3>@keyframes</h3>\n    <pre><code class="language-css">@keyframes slide-in {\n  0%   { transform: translateY(-24dp); opacity: 0; }\n  100% { transform: translateY(0);     opacity: 1; }\n}\n.modal-open { animation: slide-in 200ms ease-out; }\n\n@keyframes fade-pulse {\n  0%, 100% { opacity: 1; }\n  50%      { opacity: 0.5; }\n}\n.loading { animation: fade-pulse 1.2s ease-in-out infinite; }</code></pre>\n    <p data-lang="zh">支持：timing-function、iteration-count、direction、fill-mode、delay、play-state。</p>\n    <p data-lang="en">Supports: timing-function, iteration-count, direction, fill-mode, delay, play-state.</p>\n  </div>\n\n  <div class="subsection" style="margin-top:12px">\n    <h3>animation-watch <span data-lang="zh">元素</span><span data-lang="en">Element</span></h3>\n    <p data-lang="zh"><code>animation-watch</code> 观察 CSS 动画状态并通过事件桥发送 JSON payload 给 Blueprint。详见扩展元素章节。</p>\n    <p data-lang="en"><code>animation-watch</code> observes CSS animation state and sends JSON payloads to Blueprint. See the Extensions section for details.</p>\n  </div>"}', 0);
INSERT INTO content_blocks (section_id, type, content_json, sort_order) VALUES ((SELECT id FROM sections WHERE slug='ext-animation-watch' AND plugin_id=(SELECT id FROM plugins WHERE slug='WebUIX')), 'html', '{"html":"<p data-lang="zh"><code>&lt;animation-watch&gt;</code> 观察指定范围内的 CSS transition / animation 状态变化，并通过事件桥将包含动画名、进度、当前值等信息的 JSON payload 发送给 Blueprint。适合做连击动效、过场动画完成的回调等。</p>\n  <p data-lang="en"><code>&lt;animation-watch&gt;</code> observes CSS transition / animation state changes within a specified scope and sends JSON payloads containing animation name, progress, and current values to Blueprint via the event bridge. Useful for combo effects, cutscene completion callbacks, etc.</p>\n\n  <div class="subsection" style="margin-top:12px">\n    <h3><span data-lang="zh">基本用法</span><span data-lang="en">Basic Usage</span></h3>\n    <pre><code class="language-html">&lt;animation-watch id="hud-watch"\n  scope="subtree"\n  visible-only="true"\n  emit-update="true"\n  update-rate="8"\n  OnAnimationStart="OnHudAnimationStart"\n  OnAnimationUpdate="OnHudAnimationUpdate"\n  OnAnimationEnd="OnHudAnimationEnd"\n  OnAnimationCancel="OnHudAnimationCancel"&gt;\n  &lt;div class="animated-card"&gt;Reward&lt;/div&gt;\n&lt;/animation-watch&gt;</code></pre>\n  </div>\n\n  <div class="grid2" style="margin-top:12px">\n    <div class="card">\n      <h4><span data-lang="zh">范围控制</span><span data-lang="en">Scope</span></h4>\n      <p data-lang="zh"><code>scope</code> 支持 <code>self</code>（仅自身）、<code>children</code>（直接子元素）、<code>subtree</code>（所有后代）。大量节点同时动效时优先缩小范围。</p>\n      <p data-lang="en"><code>scope</code> supports <code>self</code> (element only), <code>children</code> (direct children), <code>subtree</code> (all descendants). Narrow scope when many nodes animate at once.</p>\n    </div>\n    <div class="card">\n      <h4><span data-lang="zh">可见性过滤</span><span data-lang="en">Visibility Filter</span></h4>\n      <p data-lang="zh"><code>visible-only="true"</code>（默认）跳过 display:none / visibility:hidden 的 watcher 和目标。设为 <code>false</code> 可监听隐藏元素。</p>\n      <p data-lang="en"><code>visible-only="true"</code> (default) skips watchers and targets hidden by display:none / visibility:hidden. Set to <code>false</code> to include hidden targets.</p>\n    </div>\n    <div class="card">\n      <h4><span data-lang="zh">更新频率控制</span><span data-lang="en">Update Rate</span></h4>\n      <p data-lang="zh"><code>emit-update="false"</code> 只保留 start/end/cancel 事件；<code>update-rate</code> 限制 update 频率（Hz），<code>0</code> 表示不连续派发。</p>\n      <p data-lang="en"><code>emit-update="false"</code> keeps only start/end/cancel. <code>update-rate</code> throttles update events in Hz; <code>0</code> disables continuous dispatch.</p>\n    </div>\n    <div class="card">\n      <h4><span data-lang="zh">事件 Payload</span><span data-lang="en">Event Payload</span></h4>\n      <p data-lang="zh">JSON 包含 <code>type</code>、<code>watchId</code>、<code>targetId</code>、<code>name</code>、<code>property</code>、<code>elapsed</code>、<code>duration</code>、<code>progress</code>、<code>currentValue</code> 等字段。</p>\n      <p data-lang="en">JSON includes <code>type</code>, <code>watchId</code>, <code>targetId</code>, <code>name</code>, <code>property</code>, <code>elapsed</code>, <code>duration</code>, <code>progress</code>, <code>currentValue</code>, etc.</p>\n    </div>\n  </div>"}', 0);
INSERT INTO content_blocks (section_id, type, content_json, sort_order) VALUES ((SELECT id FROM sections WHERE slug='custom-components' AND plugin_id=(SELECT id FROM plugins WHERE slug='WebUIX')), 'html', '{"html":"<p data-lang="zh">WebUIX 允许在 Blueprint 中创建全新的 HTML 标签 — 不是简单模板，而是一个拥有完整生命周期的组件。内置的 <code>drag-area</code>、<code>modal</code>、<code>dropdown</code> 等扩展元素均以这种方式实现。</p>\n  <p data-lang="en">WebUIX lets you create entirely new HTML tags in Blueprint — not just templates, but full components with their own lifecycle. The built-in extensions like <code>drag-area</code>, <code>modal</code>, and <code>dropdown</code> are all implemented this way.</p>\n\n  <div class="subsection" style="margin-top:12px">\n    <h3><span data-lang="zh">快速创建</span><span data-lang="en">Quick Creation</span></h3>\n    <ol>\n      <li data-lang="zh">创建 Blueprint，父类选择 <strong>UWebUIXComponent</strong></li>\n      <li data-lang="en">Create a Blueprint with parent <strong>UWebUIXComponent</strong></li>\n      <li data-lang="zh">在 Class Settings 中填写 <code>TagName</code>（如 <code>my-card</code>）</li>\n      <li data-lang="en">Set <code>TagName</code> (e.g., <code>my-card</code>) in Class Settings</li>\n      <li data-lang="zh">编写默认 HTML 模板和 CSS — 这构成组件内部结构</li>\n      <li data-lang="en">Write default HTML template and CSS — these form the internal structure</li>\n      <li data-lang="zh">实现 <code>Construct</code> / <code>Tick</code> / <code>Destruct</code> 事件，通过 <code>Dom</code> 操作内部 DOM</li>\n      <li data-lang="en">Implement <code>Construct</code> / <code>Tick</code> / <code>Destruct</code> events, use <code>Dom</code> to manipulate internal DOM</li>\n    </ol>\n  </div>\n\n  <div class="subsection" style="margin-top:12px">\n    <h3><span data-lang="zh">暴露属性与事件 — 点击"公开"即可</span><span data-lang="en">Expose Attributes &amp; Events — Just Click Make Public</span></h3>\n    <p data-lang="zh">在 Blueprint 中编写 <code>UFUNCTION(BlueprintCallable)</code> 函数后，只需在函数上点击 <strong>公开到 HTML</strong>，该函数就会自动成为 HTML 中可用的 <code>OnXxx</code> 事件属性。同样，Blueprint 变量点击公开后，即可在 HTML 中作为自定义属性使用。</p>\n    <p data-lang="en">After writing a <code>UFUNCTION(BlueprintCallable)</code> in Blueprint, simply click <strong>Expose to HTML</strong> on the function — it automatically becomes an <code>OnXxx</code> event attribute usable in HTML. Similarly, click expose on a Blueprint variable to use it as a custom attribute in HTML.</p>\n    <pre><code class="language-html">&lt;!-- Exposed as event: bind directly in HTML --&gt;\n&lt;my-card title="Sword" OnCardClicked="OnSwordPicked(id)" OnRarityChanged="OnRarityUpdate(rarity)"&gt;&lt;/my-card&gt;\n\n&lt;!-- Exposed as attribute: pass values like native attributes --&gt;\n&lt;my-card title="Sword of Light" badge="{{Model.NewItems}}" rarity="epic" locked="true"&gt;\n  &lt;p&gt;A legendary weapon.&lt;/p&gt;\n&lt;/my-card&gt;\n\n&lt;!-- Exposed as function: call directly in templates --&gt;\n&lt;span&gt;{{UE::CallText(GetCardStatus)}}&lt;/span&gt;</code></pre>\n    <p data-lang="zh">编辑器的 HTML 代码补全会自动列出所有已注册组件的自定义属性、事件和函数，无需手动查找。</p>\n    <p data-lang="en">The editor''s HTML autocomplete automatically lists all registered component custom attributes, events, and functions — no manual lookup needed.</p>\n  </div>\n\n  <div class="subsection" style="margin-top:12px">\n    <h3><span data-lang="zh">注册组件</span><span data-lang="en">Register Component</span></h3>\n    <p data-lang="zh"><strong>全局</strong>：添加到 Project Settings → WebUIX → Components，所有文档可用。<br><strong>文档级</strong>：添加到 UWebUIXHtmlDocument 的 Components 数组，仅该文档可用。</p>\n    <p data-lang="en"><strong>Global</strong>: Add to Project Settings → WebUIX → Components for all documents.<br><strong>Per-document</strong>: Add to the UWebUIXHtmlDocument Components array for one document.</p>\n  </div>\n\n  <div class="subsection" style="margin-top:12px">\n    <h3>DOM API</h3>\n    <pre><code class="language-cpp">Dom->GetElementById("my-id");\nDom->QuerySelector(".my-class");\nDom->SetAttribute("badge", "5");\nDom->ClassListAdd("highlight");\nDom->StyleSetProperty("color", "#ff0");\nDom->SetTextContent("Updated!");\nDom->AppendChild(newElement);</code></pre>\n  </div>\n\n  <div class="img-gallery" data-gallery-id="1"></div>\n  <div class="row-img">\n    <div class="img-gallery" data-gallery-id="4"></div>\n    <div class="img-gallery" data-gallery-id="5"></div>\n  </div>"}', 0);
INSERT INTO content_blocks (section_id, type, content_json, sort_order) VALUES ((SELECT id FROM sections WHERE slug='data-binding' AND plugin_id=(SELECT id FROM plugins WHERE slug='WebUIX')), 'html', '{"html":"<div class="subsection">\n    <h3><span data-lang="zh">上下文变量 <code>{{变量}}</code></span><span data-lang="en">Context Variables</span></h3>\n    <p data-lang="zh">从 Widget Blueprint 或 Bridge Target 的同名属性读取值。调用 <code>NotifyContextChanged("VariableName")</code> 刷新。</p>\n    <p data-lang="en">Reads a property by name from Widget or Bridge Target. Call <code>NotifyContextChanged("VariableName")</code> to refresh.</p>\n    <pre><code class="language-html">&lt;span&gt;{{PlayerName}}&lt;/span&gt;\n&lt;div style=&quot;width: {{Percent}}%;&quot;&gt;{{Score}}&lt;/div&gt;</code></pre>\n  </div>\n\n  <div class="subsection" style="margin-top:12px">\n    <h3><span data-lang="zh">数据模型 <code>{{Model.Key}}</code></span><span data-lang="en">Data Model</span></h3>\n    <p data-lang="zh">通过 SetModelString/SetModelNumber/SetModelBool 写入，HTML 中用 {{Model.Key}} 读取。</p>\n    <p data-lang="en">Write via SetModelString/SetModelNumber/SetModelBool; read in HTML as {{Model.Key}}.</p>\n    <pre><code class="language-cpp">Widget->SetModelString("PlayerName", "Alice");\nWidget->SetModelNumber("Health", 85.0f);\nWidget->SetModelBool("IsAlive", true);\nWidget->NotifyContextChanged();</code></pre>\n  </div>\n\n  <div class="subsection" style="margin-top:12px">\n    <h3><span data-lang="zh">本地化 <code>{{loc:key|fallback}}</code></span><span data-lang="en">Localization</span></h3>\n    <pre><code class="language-html">&lt;span&gt;{{loc:ui.start_button|Start Game}}&lt;/span&gt;\n&lt;span&gt;{{loc:hud.health|Health}}: {{Model.Health}}&lt;/span&gt;</code></pre>\n    <p data-lang="zh">运行时切换语言：<code>Widget->SetCulture("zh-Hans"); Widget->RefreshLocalization();</code></p>\n    <p data-lang="en">Switch culture at runtime: <code>Widget->SetCulture("zh-Hans"); Widget->RefreshLocalization();</code></p>\n  </div>\n\n  <div class="subsection" style="margin-top:12px">\n    <h3><span data-lang="zh">UE 内置统计 <code>{{UE::FPS}}</code></span><span data-lang="en">UE Built-in Stats</span></h3>\n    <table>\n      <tr><th>Token</th><th><span data-lang="zh">说明</span><span data-lang="en">Description</span></th></tr>\n      <tr><td><code>{{UE::FPS}}</code></td><td data-lang="zh">当前帧率</td><td data-lang="en">Current FPS</td></tr>\n      <tr><td><code>{{UE::FrameMs}}</code></td><td data-lang="zh">总帧时间 (ms)</td><td data-lang="en">Frame time (ms)</td></tr>\n      <tr><td><code>{{UE::UpdateMs}}</code></td><td data-lang="zh">DOM 更新时间 (ms)</td><td data-lang="en">DOM update time</td></tr>\n      <tr><td><code>{{UE::RenderMs}}</code></td><td data-lang="zh">渲染时间 (ms)</td><td data-lang="en">Render time</td></tr>\n      <tr><td><code>{{UE::RhiDraws}}</code></td><td data-lang="zh">RHI 绘制调用数</td><td data-lang="en">RHI draw call count</td></tr>\n      <tr><td><code>{{UE::WidgetWidth}}</code> / <code>{{UE::WidgetHeight}}</code></td><td data-lang="zh">控件显示尺寸</td><td data-lang="en">Widget display size</td></tr>\n    </table>\n  </div>\n\n  <div class="subsection" style="margin-top:12px">\n    <h3>UE::CallText / UE::CallHtml</h3>\n    <p data-lang="zh">调用 UFUNCTION 并将返回值插入 HTML 中。CallText 插为纯文本，CallHtml 插为 HTML 片段。</p>\n    <p data-lang="en">Call UFUNCTION and insert return value into HTML. CallText inserts as plain text; CallHtml inserts as HTML fragment.</p>\n    <pre><code class="language-html">&lt;h2&gt;{{UE::CallText(GetPanelTitle)}}&lt;/h2&gt;\n&lt;span&gt;{{UE::CallText(FormatScore, Value=Model.Score)}}&lt;/span&gt;\n&lt;div html=&quot;UE::CallHtml(BuildInventoryRows)&quot;&gt;&lt;/div&gt;</code></pre>\n  </div>\n\n  <div class="subsection" style="margin-top:12px">\n    <h3><span data-lang="zh">模板指令</span><span data-lang="en">Template Directives</span></h3>\n    <pre><code class="language-html">&lt;!-- forEach loop --&gt;\n&lt;template foreach=&quot;item in Model.Items&quot;&gt;\n  &lt;div class=&quot;item-row&quot;&gt;{{item.Name}} &amp;times; {{item.Count}}&lt;/div&gt;\n&lt;/template&gt;\n\n&lt;!-- Conditional rendering --&gt;\n&lt;template if=&quot;{{Model.IsLoggedIn}}&quot;&gt;\n  &lt;div class=&quot;welcome&quot;&gt;Welcome, {{PlayerName}}!&lt;/div&gt;\n&lt;/template&gt;\n&lt;template else&gt;\n  &lt;div class=&quot;login-prompt&quot;&gt;Please log in.&lt;/div&gt;\n&lt;/template&gt;\n\n&lt;!-- switch --&gt;\n&lt;template switch=&quot;{{Model.Tab}}&quot;&gt;\n  &lt;template case=&quot;inventory&quot;&gt;&lt;div&gt;Inventory&lt;/div&gt;&lt;/template&gt;\n  &lt;template case=&quot;shop&quot;&gt;&lt;div&gt;Shop&lt;/div&gt;&lt;/template&gt;\n  &lt;template default&gt;&lt;div&gt;Unknown&lt;/div&gt;&lt;/template&gt;\n&lt;/template&gt;\n\n&lt;!-- show visibility control --&gt;\n&lt;div show=&quot;{{Model.HasBonus}}&quot;&gt;Bonus Active!&lt;/div&gt;</code></pre>\n  </div>"}', 0);
INSERT INTO content_blocks (section_id, type, content_json, sort_order) VALUES ((SELECT id FROM sections WHERE slug='event-bridge' AND plugin_id=(SELECT id FROM plugins WHERE slug='WebUIX')), 'html', '{"html":"<p data-lang="zh">通过 HTML 事件属性调用 Blueprint UFUNCTION，按函数名查找 Widget 或 Bridge Target。</p>\n  <p data-lang="en">Call Blueprint UFUNCTIONs via HTML event attributes; looked up by name on Widget or Bridge Target.</p>\n\n  <div class="subsection" style="margin-top:12px">\n    <h3><span data-lang="zh">支持的事件</span><span data-lang="en">Supported Events</span></h3>\n    <table>\n      <tr><th><span data-lang="zh">事件</span><span data-lang="en">Event</span></th><th><span data-lang="zh">触发时机</span><span data-lang="en">Trigger</span></th></tr>\n      <tr><td><code>OnClick</code></td><td data-lang="zh">鼠标/触摸点击释放</td><td data-lang="en">Mouse/touch click release</td></tr>\n      <tr><td><code>OnDblClick</code></td><td data-lang="zh">双击</td><td data-lang="en">Double click</td></tr>\n      <tr><td><code>OnInput</code></td><td data-lang="zh">输入值变化（每次按键）</td><td data-lang="en">Input value changing (each keystroke)</td></tr>\n      <tr><td><code>OnChange</code></td><td data-lang="zh">值提交（blur/Enter/松开）</td><td data-lang="en">Value committed (blur/Enter/release)</td></tr>\n      <tr><td><code>OnFocus</code></td><td data-lang="zh">获得焦点</td><td data-lang="en">Element receives focus</td></tr>\n      <tr><td><code>OnBlur</code></td><td data-lang="zh">失去焦点</td><td data-lang="en">Element loses focus</td></tr>\n      <tr><td><code>OnKeyDown</code> / <code>OnKeyUp</code></td><td data-lang="zh">键盘按下/释放</td><td data-lang="en">Key down/up</td></tr>\n      <tr><td><code>OnOpen</code> / <code>OnClose</code></td><td data-lang="zh">元素打开/关闭</td><td data-lang="en">Element opens/closes</td></tr>\n      <tr><td><code>OnDragstart</code> / <code>OnDrag</code> / <code>OnDragend</code></td><td data-lang="zh">拖拽开始/移动/结束</td><td data-lang="en">Drag start/move/end</td></tr>\n      <tr><td><code>OnDragover</code> / <code>OnDragout</code> / <code>OnDragdrop</code></td><td data-lang="zh">拖拽悬停/离开/放下</td><td data-lang="en">Drag over/out/drop</td></tr>\n      <tr><td><code>OnAnimationStart</code> / <code>OnAnimationUpdate</code> / <code>OnAnimationEnd</code> / <code>OnAnimationCancel</code></td><td data-lang="zh">动画生命周期</td><td data-lang="en">Animation lifecycle</td></tr>\n    </table>\n  </div>\n\n  <div class="subsection" style="margin-top:12px">\n    <h3><span data-lang="zh">使用示例</span><span data-lang="en">Usage Examples</span></h3>\n    <pre><code class="language-html">&lt;button OnClick=&quot;StartGame&quot;&gt;Start&lt;/button&gt;\n&lt;button OnClick=&quot;OpenSettings(panel=''video'')&quot;&gt;Settings&lt;/button&gt;\n\n&lt;input value=&quot;{{Model.SearchText}}&quot; OnChange=&quot;OnSearchChanged(value)&quot; /&gt;\n&lt;input value=&quot;{{Model.Name}}&quot; OnInput=&quot;OnNameInput(value)&quot; /&gt;\n\n&lt;div class=&quot;item-slot&quot; OnClick=&quot;OnSlotClicked(id)&quot; /&gt;\n&lt;drag-area OnDrop=&quot;OnItemDropped(event, id)&quot; /&gt;</code></pre>\n  </div>\n\n  <div class="subsection" style="margin-top:12px">\n    <h3>Bridge Object</h3>\n    <p data-lang="zh">创建 UWebUIXBridgeObject，设置 TargetObject，赋给 Widget 的 BridgeObject 属性。事件按名称路由到目标对象。</p>\n    <p data-lang="en">Create a UWebUIXBridgeObject, set TargetObject, assign to Widget BridgeObject. Events route to the target by name.</p>\n  </div>\n\n  <div class="subsection" style="margin-top:12px">\n    <h3><span data-lang="zh">UMG 导航 (nav-order)</span><span data-lang="en">UMG Navigation</span></h3>\n    <p data-lang="zh">通过 <code>nav-order</code> 属性控制手柄/键盘导航顺序：</p>\n    <p data-lang="en">Control gamepad/keyboard navigation order via <code>nav-order</code>:</p>\n    <pre><code class="language-html">&lt;button nav-order=&quot;10&quot;&gt;First&lt;/button&gt;\n&lt;button nav-order=&quot;20&quot;&gt;Second&lt;/button&gt;\n&lt;button nav-order=&quot;auto&quot;&gt;Auto&lt;/button&gt;\n&lt;div nav-order=&quot;none&quot;&gt;Skipped&lt;/div&gt;</code></pre>\n  </div>"}', 0);
INSERT INTO content_blocks (section_id, type, content_json, sort_order) VALUES ((SELECT id FROM sections WHERE slug='ext-drag' AND plugin_id=(SELECT id FROM plugins WHERE slug='WebUIX')), 'html', '{"html":"<div class="subsection">\n    <h3><span data-lang="zh">网格拖拽</span><span data-lang="en">Grid Drag</span></h3>\n    <pre><code class="language-html">&lt;drag-area id=&quot;bag&quot; columns=&quot;5&quot; rows=&quot;4&quot; count=&quot;13&quot; gap=&quot;8dp&quot;\n  drag-anchor=&quot;center&quot; OnDragdrop=&quot;OnBagDrop(TargetId)&quot;&gt;\n  &lt;drag-cell class=&quot;slot&quot;&gt;\n    &lt;span&gt;#{{dragCell::DisplayIndex}}&lt;/span&gt;\n    &lt;span&gt;{{dragCell::DisplayCol}},{{dragCell::DisplayRow}}&lt;/span&gt;\n  &lt;/drag-cell&gt;\n  &lt;drag-item id=&quot;sword&quot; col=&quot;0&quot; row=&quot;0&quot; cols=&quot;2&quot; rows=&quot;2&quot;\n    OnDragstart=&quot;OnItemDragStart&quot; OnDragend=&quot;OnItemDragEnd&quot;&gt;\n    &lt;b&gt;2x2&lt;/b&gt;\n  &lt;/drag-item&gt;\n&lt;/drag-area&gt;</code></pre>\n    <p data-lang="zh">模板变量：<code>{{dragCell::DisplayIndex}}</code> <code>{{dragArea::UsableCount}}</code> <code>{{dragItem::PreviewValid}}</code>。可通过 <code>var-scope="Inventory"</code> 重命名作用域。</p>\n    <p data-lang="en">Template variables: <code>{{dragCell::DisplayIndex}}</code> <code>{{dragArea::UsableCount}}</code> <code>{{dragItem::PreviewValid}}</code>. Rename scope with <code>var-scope="Inventory"</code>.</p>\n  </div>\n\n  <div class="subsection" style="margin-top:12px">\n    <h3><span data-lang="zh">自由拖拽（浮动面板）</span><span data-lang="en">Free Drag (Floating Panel)</span></h3>\n    <pre><code class="language-html">&lt;div id=&quot;panel&quot; class=&quot;floating-panel&quot;&gt;\n  &lt;handle class=&quot;title-bar&quot; move_target=&quot;panel&quot; edge_margin=&quot;0dp&quot;&gt;\n    Drag Panel\n  &lt;/handle&gt;\n  &lt;p&gt;This panel can be moved by dragging the title bar.&lt;/p&gt;\n&lt;/div&gt;</code></pre>\n    <p data-lang="zh"><code>handle</code> 元素通过 <code>move_target</code> 指定被拖拽的目标，<code>edge_margin</code> 限制边界。拖拽预览渲染在独立透明 RT 上，主页面纹理不会被修改。</p>\n    <p data-lang="en"><code>handle</code> specifies the drag target via <code>move_target</code>, <code>edge_margin</code> constrains bounds. Drag preview renders on a separate transparent RT; main page texture is never modified.</p>\n  </div>\n\n  <div class="subsection" style="margin-top:12px">\n    <h3><span data-lang="zh">拖拽状态 CSS</span><span data-lang="en">Drag State CSS</span></h3>\n    <pre><code class="language-css">drag-cell.slot:hot { background: #38bdf833; }\ndrag-cell.slot:occupied { border-color: #f59e0b; }\ndrag-item.item:dragging { opacity: .72; transform: scale(1.04); }\ndrag-item.item:invalid { filter: drop-shadow(0 0 8dp #ef4444); }</code></pre>\n  </div>\n  <div class="row-img">\n    <div class="img-gallery" data-gallery-id="9"></div>\n    <div class="img-gallery" data-gallery-id="10"></div>\n  </div>"}', 0);
INSERT INTO content_blocks (section_id, type, content_json, sort_order) VALUES ((SELECT id FROM sections WHERE slug='ext-forms' AND plugin_id=(SELECT id FROM plugins WHERE slug='WebUIX')), 'html', '{"html":"<div class="subsection">\n    <h3>radio-group / radio-option</h3>\n    <pre><code class="language-html">&lt;radio-group value=&quot;comfortable&quot; name=&quot;Density&quot; OnChange=&quot;OnRadioChanged(value)&quot;&gt;\n  &lt;radio-option value=&quot;compact&quot;&gt;Compact&lt;/radio-option&gt;\n  &lt;radio-option value=&quot;comfortable&quot; selected&gt;Comfortable&lt;/radio-option&gt;\n  &lt;radio-option value=&quot;debug&quot;&gt;Debug&lt;/radio-option&gt;\n&lt;/radio-group&gt;</code></pre>\n  </div>\n\n  <div class="subsection" style="margin-top:12px">\n    <h3>checkbox-group / checkbox-option</h3>\n    <pre><code class="language-html">&lt;checkbox-group value=&quot;svg,animation&quot; OnInput=&quot;OnFeaturesInput(value)&quot;&gt;\n  &lt;checkbox-option value=&quot;svg&quot; selected&gt;SVG&lt;/checkbox-option&gt;\n  &lt;checkbox-option value=&quot;animation&quot; selected&gt;Animation&lt;/checkbox-option&gt;\n  &lt;checkbox-option value=&quot;ime&quot;&gt;IME&lt;/checkbox-option&gt;\n&lt;/checkbox-group&gt;</code></pre>\n    <p data-lang="zh">多选值按 DOM 顺序保存为逗号分隔字符串。</p>\n    <p data-lang="en">Multiple values stored as comma-separated string in DOM order.</p>\n  </div>\n\n  <div class="subsection" style="margin-top:12px">\n    <h3>dropdown / dropdown-option</h3>\n    <p data-lang="zh">支持单选和多选（<code>multiple="true"</code>）。打开时菜单在内部 Popup Layer 绘制，DOM 和事件冒泡保持在 dropdown 内。</p>\n    <p data-lang="en">Supports single and multi-select (<code>multiple="true"</code>). Menu paints in internal Popup Layer; DOM and event bubbling stays inside dropdown.</p>\n    <pre><code class="language-html">&lt;dropdown value=&quot;rhi&quot; placeholder=&quot;Select mode&quot;\n  OnChange=&quot;OnDropdownChanged(value)&quot;&gt;\n  &lt;dropdown-option value=&quot;rhi&quot; selected&gt;RHI&lt;/dropdown-option&gt;\n  &lt;dropdown-option value=&quot;slate&quot;&gt;Slate fallback&lt;/dropdown-option&gt;\n&lt;/dropdown&gt;</code></pre>\n  </div>"}', 0);
INSERT INTO content_blocks (section_id, type, content_json, sort_order) VALUES ((SELECT id FROM sections WHERE slug='ext-modal' AND plugin_id=(SELECT id FROM plugins WHERE slug='WebUIX')), 'html', '{"html":"<div class="subsection">\n    <h3>modal</h3>\n    <p data-lang="zh">通过 <code>value="true|false"</code> 控制。<code>modal-title</code> 和 <code>modal-footer</code> 自定义标签；不写 footer 则自动生成按钮。</p>\n    <p data-lang="en">Controlled by <code>value="true|false"</code>. <code>modal-title</code> and <code>modal-footer</code> custom tags; auto-generates buttons when footer is omitted.</p>\n    <pre><code class="language-html">&lt;button modal-action=&quot;open&quot; modal-target=&quot;settings-modal&quot;&gt;Open&lt;/button&gt;\n&lt;modal id=&quot;settings-modal&quot; value=&quot;{{SettingsModalOpen}}&quot;\n  width=&quot;420dp&quot; mask=&quot;true&quot; close-on-click-modal=&quot;true&quot;\n  close-on-press-escape=&quot;true&quot; lock-scroll=&quot;true&quot;\n  OnChange=&quot;OnSettingsModalChanged(value)&quot;&gt;\n  &lt;modal-title&gt;Settings&lt;/modal-title&gt;\n  &lt;modal-footer&gt;\n    &lt;button modal-action=&quot;cancel&quot;&gt;Cancel&lt;/button&gt;\n    &lt;button modal-action=&quot;confirm&quot;&gt;Confirm&lt;/button&gt;\n  &lt;/modal-footer&gt;\n&lt;/modal&gt;</code></pre>\n  </div>\n\n  <div class="subsection" style="margin-top:12px">\n    <h3>tooltips</h3>\n    <pre><code class="language-html">&lt;tooltips placement=&quot;top&quot; effect=&quot;dark&quot;&gt;\n  &lt;button&gt;Hover me&lt;/button&gt;\n  &lt;tooltips-content&gt;\n    &lt;b&gt;Tip title&lt;/b&gt;\n    &lt;p&gt;Explain this setting.&lt;/p&gt;\n  &lt;/tooltips-content&gt;\n&lt;/tooltips&gt;</code></pre>\n  </div>"}', 0);
INSERT INTO content_blocks (section_id, type, content_json, sort_order) VALUES ((SELECT id FROM sections WHERE slug='ext-password' AND plugin_id=(SELECT id FROM plugins WHERE slug='WebUIX')), 'html', '{"html":"<div class="subsection">\n    <h3>password</h3>\n    <p data-lang="zh">内部管理原生 password/text 输入和眼睛切换按钮。支持 <code>visible="true|false"</code> <code>show-toggle="true|false"</code> <code>disabled</code>。</p>\n    <p data-lang="en">Owns a native password/text input and eye toggle. Supports <code>visible="true|false"</code> <code>show-toggle="true|false"</code> <code>disabled</code>.</p>\n    <pre><code class="language-html">&lt;password value=&quot;&quot; placeholder=&quot;Access code&quot;\n  name=&quot;AccessCode&quot; OnInput=&quot;OnAccessCodeInput(value)&quot; /&gt;</code></pre>\n  </div>"}', 0);
INSERT INTO content_blocks (section_id, type, content_json, sort_order) VALUES ((SELECT id FROM sections WHERE slug='perf-pipeline' AND plugin_id=(SELECT id FROM plugins WHERE slug='WebUIX')), 'html', '{"html":"<p data-lang="zh">WebUIX 使用保留渲染架构，每帧仅重新绘制发生变化的区域。</p>\n  <p data-lang="en">WebUIX uses a retained rendering architecture; only changed regions are redrawn each frame.</p>\n  <pre><code>HTML + CSS -> DOM -> Style Cascade -> Layout -> Display List -> RHI Render Target -> Slate Present</code></pre>\n\n  <div class="grid2" style="margin-top:16px">\n    <div class="card">\n      <h4><span data-lang="zh">瓦片绘制缓存</span><span data-lang="en">Tile Paint Cache</span></h4>\n      <p data-lang="zh">页面分为瓦片，稳定区域不重绘。仅脏瓦片被标记并重新光栅化。</p>\n      <p data-lang="en">Page is divided into tiles; stable regions are not redrawn. Only dirty tiles are invalidated and re-rasterized.</p>\n    </div>\n    <div class="card">\n      <h4><span data-lang="zh">Last-Frame-Wins</span></h4>\n      <p data-lang="zh">高频交互采用 latest-frame-wins 策略：旧视觉帧可以丢弃，最终状态保持准确。</p>\n      <p data-lang="en">High-frequency interaction uses latest-frame-wins: stale visual frames may be skipped while final state remains correct.</p>\n    </div>\n    <div class="card">\n      <h4><span data-lang="zh">独立拖拽预览</span></h4>\n      <p data-lang="zh">拖拽预览渲染在独立透明 RT 上 — 主页面纹理在拖拽过程中不会被修改。</p>\n      <p data-lang="en">Drag preview renders on a separate transparent RT — the main page texture is never modified during drags.</p>\n    </div>\n    <div class="card">\n      <h4><span data-lang="zh">避免不必要的 DOM 变更</span></h4>\n      <p data-lang="zh">优先使用 StyleSetProperty、ClassListAdd/Remove/Toggle、SetModelNumber + NotifyContextChanged 而非结构性 DOM 变更。</p>\n      <p data-lang="en">Prefer StyleSetProperty, ClassListAdd/Remove/Toggle, SetModelNumber + NotifyContextChanged over structural DOM changes.</p>\n    </div>\n  </div>"}', 0);
INSERT INTO content_blocks (section_id, type, content_json, sort_order) VALUES ((SELECT id FROM sections WHERE slug='perf-pool' AND plugin_id=(SELECT id FROM plugins WHERE slug='WebUIX')), 'html', '{"html":"<p data-lang="zh"><strong>UWebUIXWidgetPoolComponent</strong> 管理 Widget 实例池，实现即时的页面切换。池中的 Widget 在隐藏/显示周期中保留 DOM 状态、滚动位置和输入焦点。</p>\n  <p data-lang="en"><strong>UWebUIXWidgetPoolComponent</strong> manages a pool of Widget instances for instant page switching. Pooled widgets retain their DOM state, scroll position, and input focus across hide/show cycles.</p>\n\n  <div class="subsection" style="margin-top:12px">\n    <h3><span data-lang="zh">使用方式</span><span data-lang="en">Usage</span></h3>\n    <pre><code class="language-cpp">// C++\nPoolComponent->ShowWebUIXWidget(MyWidgetClass, ViewportZOrder);\nPoolComponent->HideWebUIXWidget(MyWidgetClass);\n// Calling Show again reuses the same instance — no recreation</code></pre>\n    <p data-lang="zh">Blueprint 中对应节点：<code>Show WebUIX Widget</code> → <code>Hide WebUIX Widget</code> → <code>Show WebUIX Widget</code>（复用实例）。</p>\n    <p data-lang="en">Blueprint nodes: <code>Show WebUIX Widget</code> → <code>Hide WebUIX Widget</code> → <code>Show WebUIX Widget</code> (reuses instance).</p>\n  </div>"}', 0);
INSERT INTO content_blocks (section_id, type, content_json, sort_order) VALUES ((SELECT id FROM sections WHERE slug='perf-warmup' AND plugin_id=(SELECT id FROM plugins WHERE slug='WebUIX')), 'html', '{"html":"<p data-lang="zh"><strong>UWebUIXStartupWarmupSubsystem</strong> 在游戏启动时自动扫描已 Cook 的 Widget Blueprint，预加载文档和资源。首次打开 UI 零延迟。</p>\n  <p data-lang="en"><strong>UWebUIXStartupWarmupSubsystem</strong> automatically scans cooked Widget Blueprints at game start and preloads documents and resources. Zero delay on first UI open.</p>\n\n  <div class="subsection" style="margin-top:12px">\n    <h3><span data-lang="zh">配置条件</span><span data-lang="en">Configuration</span></h3>\n    <ol>\n      <li data-lang="zh">Widget Blueprint 父类必须是 <strong>UWebUIXUserWidget</strong>。</li>\n      <li data-lang="en">Widget Blueprint parent class must be <strong>UWebUIXUserWidget</strong>.</li>\n      <li data-lang="zh">设置 <code>bWarmupOnGameStart = true</code>。</li>\n      <li data-lang="en">Set <code>bWarmupOnGameStart = true</code>.</li>\n      <li data-lang="zh">必须设置 <code>DocumentAsset</code>。</li>\n      <li data-lang="en"><code>DocumentAsset</code> must be set.</li>\n    </ol>\n  </div>\n\n  <div class="subsection" style="margin-top:12px">\n    <h3><span data-lang="zh">预热模式</span><span data-lang="en">Warmup Modes</span></h3>\n    <table>\n      <tr><th><span data-lang="zh">模式</span><span data-lang="en">Mode</span></th><th><span data-lang="zh">说明</span><span data-lang="en">Description</span></th></tr>\n      <tr><td><code>DocumentCacheOnly</code></td><td data-lang="zh">异步后台预加载文档和 Cooked 资源（推荐）</td><td data-lang="en">Async background preload of documents and cooked resources (recommended)</td></tr>\n      <tr><td><code>PrecreateHiddenWidget</code></td><td data-lang="zh">创建 Widget、以 Collapsed 状态加入视口、调用 PrewarmDocument()。之后用 ShowPrewarmedWidget() 立即显示。</td><td data-lang="en">Creates Widget, adds to viewport as Collapsed, calls PrewarmDocument(). Use ShowPrewarmedWidget() for instant display.</td></tr>\n    </table>\n  </div>"}', 0);
INSERT INTO content_blocks (section_id, type, content_json, sort_order) VALUES ((SELECT id FROM sections WHERE slug='perf-cook' AND plugin_id=(SELECT id FROM plugins WHERE slug='WebUIX')), 'html', '{"html":"<p data-lang="zh">UWebUIXHtmlDocument 在保存/Cook 时生成预计算数据，运行时直接使用，无需文件 I/O 或重新解析。</p>\n  <p data-lang="en">UWebUIXHtmlDocument generates precomputed data at save/cook time. Runtime uses this directly — no file I/O or re-parsing.</p>\n\n  <div class="subsection" style="margin-top:12px">\n    <h3><span data-lang="zh">预计算内容</span><span data-lang="en">Precomputed Data</span></h3>\n    <table>\n      <tr><th><span data-lang="zh">数据</span><span data-lang="en">Data</span></th><th><span data-lang="zh">说明</span><span data-lang="en">Description</span></th></tr>\n      <tr><td><code>ResolvedHtmlBundle</code></td><td data-lang="zh">合并后的 HTML + 链接的 CSS</td><td data-lang="en">Merged HTML + linked CSS</td></tr>\n      <tr><td><code>CookedDomNodes</code></td><td data-lang="zh">预解析的 DOM 树</td><td data-lang="en">Pre-parsed DOM tree</td></tr>\n      <tr><td><code>CookedStyleSheet</code></td><td data-lang="zh">已解析的样式表</td><td data-lang="en">Resolved stylesheet</td></tr>\n      <tr><td><code>CookedImageResources</code></td><td data-lang="zh">压缩后的图片字节（PNG/JPG）</td><td data-lang="en">Compressed image bytes (PNG/JPG)</td></tr>\n      <tr><td><code>ReferencedAssets</code></td><td data-lang="zh">文档引用的所有 UE 资产（图片、音频等软引用）</td><td data-lang="en">All UE assets referenced by the document (images, audio, etc. as soft references)</td></tr>\n    </table>\n  </div>\n  <div class="callout">\n    <p data-lang="zh">修改 HTML/CSS 源码后调用 <code>UWebUIXHtmlDocument::RefreshDerivedData()</code> 更新资产派生信息。</p>\n    <p data-lang="en">After editing HTML/CSS source, call <code>UWebUIXHtmlDocument::RefreshDerivedData()</code> to update derived asset data.</p>\n  </div>"}', 0);
INSERT INTO content_blocks (section_id, type, content_json, sort_order) VALUES ((SELECT id FROM sections WHERE slug='inspector' AND plugin_id=(SELECT id FROM plugins WHERE slug='WebUIX')), 'html', '{"html":"<p data-lang="zh">内置调试工具，Editor/PIE 下可用。焦点落在 WebUIX 画面后按 <strong>F8</strong> 打开或关闭。</p>\n  <p data-lang="en">Built-in debug tool, available in Editor/PIE. Focus a WebUIX view and press <strong>F8</strong> to toggle.</p>\n\n  <div class="grid2" style="margin-top:16px">\n    <div class="card">\n      <h4><span data-lang="zh">元素选择器</span><span data-lang="en">Element Picker</span></h4>\n      <p data-lang="zh">使用 Pick 图标从渲染画面选择元素。Pick 模式只做 hit-test，不触发真实交互。</p>\n      <p data-lang="en">Use the Pick icon to select elements from the rendered view. Pick mode only hit-tests — no real interactions.</p>\n    </div>\n    <div class="card">\n      <h4><span data-lang="zh">DOM 树</span><span data-lang="en">DOM Tree</span></h4>\n      <p data-lang="zh">左侧显示实际渲染树（包括 WebUIX 生成的 non-DOM 节点如 selectvalue、selectarrow 等）。VSCode 风格语法配色，Ctrl+C 复制节点文本。</p>\n      <p data-lang="en">Left panel shows the rendered tree (including generated nodes). VSCode-style syntax colors, Ctrl+C to copy.</p>\n    </div>\n    <div class="card">\n      <h4><span data-lang="zh">右侧 Tabs</span><span data-lang="en">Details Tabs</span></h4>\n      <p data-lang="zh">Styles、Computed、Layout、Attributes、Events、Bindings — 支持右键横向拖动。</p>\n      <p data-lang="en">Styles, Computed, Layout, Attributes, Events, Bindings — right-drag to scroll.</p>\n    </div>\n    <div class="card">\n      <h4><span data-lang="zh">Paint 调试</span><span data-lang="en">Paint Debug</span></h4>\n      <p data-lang="zh">Layout tab 显示 display item、paint chunk、dirty pixel 统计。选中元素可查看 paint order、bounds、cache 状态。</p>\n      <p data-lang="en">Layout tab shows display item, paint chunk, dirty pixel stats. Selected element shows paint order, bounds, cache state.</p>\n    </div>\n    <div class="card">\n      <h4><span data-lang="zh">事件模拟</span><span data-lang="en">Event Simulation</span></h4>\n      <p data-lang="zh">Events tab 提供 Hover/Unhover/Focus/Blur/Click 按钮。Pick 模式不触发控件行为，需用这些按钮模拟。</p>\n      <p data-lang="en">Events tab provides Hover/Unhover/Focus/Blur/Click buttons. Pick mode does not trigger widget behavior.</p>\n    </div>\n    <div class="card">\n      <h4><span data-lang="zh">绑定检查</span><span data-lang="en">Binding Inspection</span></h4>\n      <p data-lang="zh">Bindings tab 列出事件属性和已实现 Blueprint 函数，支持 Jump 跳转和 Copy 复制。</p>\n      <p data-lang="en">Bindings tab lists event attributes and implemented Blueprint functions with Jump and Copy.</p>\n    </div>\n  </div>\n  <div class="img-gallery" data-gallery-id="8"></div>"}', 0);
INSERT INTO content_blocks (section_id, type, content_json, sort_order) VALUES ((SELECT id FROM sections WHERE slug='debug-stats' AND plugin_id=(SELECT id FROM plugins WHERE slug='WebUIX')), 'html', '{"html":"<div class="grid2">\n    <div class="card">\n      <h4>GetLastRenderStats()</h4>\n      <p data-lang="zh">查看 RhiDrawCallCount、RhiBatchCount、RhiTextureUploadCount、BackdropFilterPassCount、FilterCompositePassCount 等约 90 个统计字段。</p>\n      <p data-lang="en">Inspect ~90 stats fields including RhiDrawCallCount, RhiBatchCount, BackdropFilterPassCount, FilterCompositePassCount.</p>\n    </div>\n    <div class="card">\n      <h4>GetLastEventDebugInfo()</h4>\n      <p data-lang="zh">查看最近一次事件桥调用，排查 HTML 事件名、参数、目标对象或 missing function warning。</p>\n      <p data-lang="en">Inspect the most recent event bridge call to debug event names, arguments, targets, or missing function warnings.</p>\n    </div>\n    <div class="card">\n      <h4><span data-lang="zh">编辑器诊断</span><span data-lang="en">Editor Diagnostics</span></h4>\n      <p data-lang="zh">HTML/CSS 编辑器底部状态栏显示诊断摘要，可跳转上一个/下一个诊断并复制诊断文本。</p>\n      <p data-lang="en">Status bar shows diagnostic summary; jump to previous/next diagnostic and copy diagnostic text.</p>\n    </div>\n    <div class="card">\n      <h4><span data-lang="zh">性能建议</span><span data-lang="en">Performance Tips</span></h4>\n      <p data-lang="zh">高频输入/hover/scroll 尽量 trigger render-only 刷新。列表批量更新优先 class、attribute 或 DataModel 批处理。</p>\n      <p data-lang="en">For high-frequency input/hover/scroll, prefer render-only refreshes. For list updates, prefer class, attribute, or DataModel batching.</p>\n    </div>\n  </div>"}', 0);
INSERT INTO content_blocks (section_id, type, content_json, sort_order) VALUES ((SELECT id FROM sections WHERE slug='blueprint-api' AND plugin_id=(SELECT id FROM plugins WHERE slug='WebUIX')), 'html', '{"html":"<p class="subtitle-sm" data-lang="zh" style="color:var(--c-muted);margin-bottom:16px">以下节点来自 WebUIX 公开 Blueprint API。每张卡片可复制 Unreal Blueprint serialized text，并显示 UE 风格节点预览。</p>\n  <p class="subtitle-sm" data-lang="en" style="color:var(--c-muted);margin-bottom:16px">Nodes below from WebUIX public Blueprint API. Each card can copy Unreal Blueprint serialized text and shows a UE-style node preview.</p>\n  <div id="api-root" class="stack"></div>"}', 0);
INSERT INTO content_blocks (section_id, type, content_json, sort_order) VALUES ((SELECT id FROM sections WHERE slug='ref-index' AND plugin_id=(SELECT id FROM plugins WHERE slug='WebUIX')), 'html', '{"html":"<p data-lang="zh">集中列出 WebUIX 常用标签、事件属性、CSS 属性和状态选择器，方便快速查找。</p>\n  <p data-lang="en">Quick reference for common tags, event attributes, CSS properties, and state selectors.</p>\n\n  <div class="subsection" style="margin-top:12px">\n    <h3><span data-lang="zh">事件属性</span><span data-lang="en">Event Attributes</span></h3>\n    <div class="code-tags">\n      <code>OnClick</code><code>OnDblClick</code><code>OnInput</code><code>OnChange</code><code>OnOpen</code><code>OnClose</code>\n      <code>OnFocus</code><code>OnBlur</code><code>OnKeyDown</code><code>OnKeyUp</code>\n      <code>OnDragstart</code><code>OnDrag</code><code>OnDragend</code><code>OnDragover</code><code>OnDragout</code><code>OnDragdrop</code>\n      <code>OnAnimationStart</code><code>OnAnimationUpdate</code><code>OnAnimationEnd</code><code>OnAnimationCancel</code>\n    </div>\n  </div>\n\n  <div class="subsection" style="margin-top:12px">\n    <h3><span data-lang="zh">CSS 属性速查</span><span data-lang="en">CSS Property Quick Ref</span></h3>\n    <div class="grid2">\n      <div class="card"><h4><span data-lang="zh">布局</span><span data-lang="en">Layout</span></h4><div class="code-tags"><code>display</code><code>position</code><code>top</code><code>right</code><code>bottom</code><code>left</code><code>width</code><code>height</code><code>overflow</code><code>z-index</code></div></div>\n      <div class="card"><h4><span data-lang="zh">盒模型</span><span data-lang="en">Box</span></h4><div class="code-tags"><code>margin</code><code>padding</code><code>border</code><code>border-radius</code><code>box-shadow</code></div></div>\n      <div class="card"><h4><span data-lang="zh">文字</span><span data-lang="en">Text</span></h4><div class="code-tags"><code>font-family</code><code>font-size</code><code>font-weight</code><code>color</code><code>text-align</code><code>line-height</code><code>letter-spacing</code><code>text-overflow</code><code>text-shadow</code></div></div>\n      <div class="card"><h4><span data-lang="zh">效果</span><span data-lang="en">Effects</span></h4><div class="code-tags"><code>opacity</code><code>transform</code><code>transition</code><code>animation</code><code>filter:blur()</code><code>filter:drop-shadow()</code><code>filter:brightness()</code><code>filter:contrast()</code><code>filter:saturate()</code><code>backdrop-filter</code></div></div>\n      <div class="card"><h4><span data-lang="zh">音效</span><span data-lang="en">Sound</span></h4><div class="code-tags"><code>background-sound</code><code>background-sound-volume</code><code>background-sound-pitch</code><code>background-sound-cooldown</code></div></div>\n      <div class="card"><h4><span data-lang="zh">背景</span><span data-lang="en">Background</span></h4><div class="code-tags"><code>background-color</code><code>background-image</code><code>background-size</code><code>linear-gradient</code><code>radial-gradient</code></div></div>\n      <div class="card"><h4>Flexbox</h4><div class="code-tags"><code>flex-direction</code><code>flex-wrap</code><code>flex</code><code>justify-content</code><code>align-items</code><code>gap</code></div></div>\n      <div class="card"><h4><span data-lang="zh">模板</span><span data-lang="en">Template</span></h4><div class="code-tags"><code>if</code><code>else-if</code><code>else</code><code>for</code><code>show</code><code>key</code></div></div>\n    </div>\n  </div>\n\n  <div class="subsection" style="margin-top:12px">\n    <h3><span data-lang="zh">输入与 IME</span><span data-lang="en">Input &amp; IME</span></h3>\n    <p data-lang="zh">Windows IME 通过 UE 文本输入接口接入。<code>OnInput</code> 实时同步、<code>OnChange</code> 提交语义、<code>OnTextInput</code> 底层字符流（中文输入不要只依赖它）。</p>\n    <p data-lang="en">Windows IME integrates via UE text input. <code>OnInput</code> for live sync, <code>OnChange</code> for committed values, <code>OnTextInput</code> for low-level character stream (don''t rely on it alone for Chinese).</p>\n  </div>"}', 0);
INSERT INTO content_blocks (section_id, type, content_json, sort_order) VALUES ((SELECT id FROM sections WHERE slug='settings' AND plugin_id=(SELECT id FROM plugins WHERE slug='WebUIX')), 'html', '{"html":"<p data-lang="zh">通过 Project Settings → Plugins → WebUIX 访问（UWebUIXSettings）。</p>\n  <p data-lang="en">Access via Project Settings → Plugins → WebUIX (UWebUIXSettings).</p>\n  <table style="margin-top:12px">\n    <tr><th>Setting</th><th><span data-lang="zh">默认</span><span data-lang="en">Default</span></th><th><span data-lang="zh">说明</span><span data-lang="en">Description</span></th></tr>\n    <tr><td><code>TargetFrameRate</code></td><td>60</td><td data-lang="zh">WebUIX 控件最大渲染帧率</td><td data-lang="en">Max render rate for WebUIX widgets</td></tr>\n    <tr><td><code>bEnableExperimentalNativeIme</code></td><td>false</td><td data-lang="zh">启用原生 Windows IME（实验性）</td><td data-lang="en">Enable native Windows IME (experimental)</td></tr>\n    <tr><td><code>bPackageWebUIXInspectorInRuntime</code></td><td>false</td><td data-lang="zh">打包时包含调试控制台（Editor/PIE 无需开启，直接按 F8）</td><td data-lang="en">Include Debug Console in packaged builds (not needed for Editor/PIE, use F8)</td></tr>\n    <tr><td><code>bAutoPrewarmDocument</code></td><td>true</td><td data-lang="zh">首次加载时自动预热文档</td><td data-lang="en">Auto pre-warm documents on first load</td></tr>\n    <tr><td><code>TextContrast</code></td><td>1.0</td><td data-lang="zh">文字渲染对比度乘数</td><td data-lang="en">Text contrast multiplier</td></tr>\n    <tr><td><code>TextGamma</code></td><td>1.0</td><td data-lang="zh">文字渲染伽马</td><td data-lang="en">Text gamma</td></tr>\n    <tr><td><code>bEnableSubpixelText</code></td><td>true</td><td data-lang="zh">子像素字体渲染</td><td data-lang="en">Subpixel font rendering</td></tr>\n    <tr><td><code>ViewportCullingPaddingPx</code></td><td>8</td><td data-lang="zh">视口裁剪额外像素</td><td data-lang="en">Extra pixels for viewport culling</td></tr>\n    <tr><td><code>DocumentRoot</code></td><td>—</td><td data-lang="zh">外置 HTML 文件根目录</td><td data-lang="en">Root directory for external HTML files</td></tr>\n    <tr><td><code>Components</code></td><td>—</td><td data-lang="zh">全局注册的自定义组件类列表</td><td data-lang="en">Globally registered custom component classes</td></tr>\n  </table>"}', 0);
INSERT INTO content_blocks (section_id, type, content_json, sort_order) VALUES ((SELECT id FROM sections WHERE slug='limitations' AND plugin_id=(SELECT id FROM plugins WHERE slug='WebUIX')), 'html', '{"html":"<ul data-lang="zh">\n    <li>支持平台：Win64、macOS、Linux、Android、iOS。</li>\n    <li>WebUIX 是自研 HTML/CSS 渲染器，不是 Chromium 浏览器；不执行 JavaScript，不加载任意网页。</li>\n    <li>不支持 <code>&lt;video&gt;</code>、<code>&lt;audio&gt;</code>、<code>&lt;canvas&gt;</code>、<code>&lt;iframe&gt;</code>。</li>\n    <li>不支持 CSS 自定义属性（<code>var(--...)</code>）— 使用模板绑定系统替代。</li>\n    <li>不支持 SVG 渲染 — 使用 PNG/JPG 图片资产。</li>\n    <li>不支持浏览器 API（<code>window</code>、<code>document</code>、<code>fetch</code>、<code>localStorage</code> 等）。</li>\n    <li>外置 .html/.css 文件适合开发期迭代；正式项目推荐使用 UWebUIXHtmlDocument / UWebUIXCssStyleSheet 资产。</li>\n    <li>IME 原生输入法（Windows）为实验性功能，其他平台使用回退模式。</li>\n    <li>无远程 URL 支持 — 所有资产必须来自 UE 资产系统或项目本地文件路径。</li>\n  </ul>\n  <ul data-lang="en">\n    <li>Supported platforms: Win64, macOS, Linux, Android, iOS.</li>\n    <li>WebUIX is a self-developed HTML/CSS renderer, not a Chromium browser. It does not execute JavaScript or load arbitrary web pages.</li>\n    <li><code>&lt;video&gt;</code>, <code>&lt;audio&gt;</code>, <code>&lt;canvas&gt;</code>, <code>&lt;iframe&gt;</code> are not supported.</li>\n    <li>CSS custom properties (<code>var(--...)</code>) are not supported — use the template binding system instead.</li>\n    <li>SVG rendering is not supported — use PNG/JPG image assets.</li>\n    <li>Browser APIs (<code>window</code>, <code>document</code>, <code>fetch</code>, <code>localStorage</code>, etc.) are not supported.</li>\n    <li>External .html/.css files are best for development iteration; for production use UWebUIXHtmlDocument / UWebUIXCssStyleSheet assets.</li>\n    <li>Native Windows IME is experimental; other platforms use fallback mode.</li>\n    <li>No remote URL support — all assets must come from the UE asset system or project-relative file paths.</li>\n  </ul>"}', 0);